3	const DEFAULT_INTERVAL_MS = 300000;
4	const MEETING_NOTE_TOOL_NAME = 'record_meeting_note_generation';
5	const RECONCILER_ACTOR = Object.freeze({
6	    authSource: 'internal',
7	    sub: 'eve_meeting_note_reconciler',
8	    person_id: 'internal_api'
9	});
10	
11	function nowIso() {
12	    return new Date().toISOString();
13	}
14	
15	function parseDurationMs(value, fallback) {
16	    const parsed = Number(value);
17	    return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
18	}
19	
20	/**
21	 * Extracts every `record_meeting_note_generation` tool-call request from an
22	 * Eve session event stream. The tool-call input carries the generated note
23	 * (org/project/run refs, source_text_hash, note.title/body) even when the
24	 * Eve-side tool execution failed, so this is the pull-side source of truth.
25	 */
26	export function extractMeetingNoteToolCalls(events) {
27	    const calls = [];
28	    for (const event of Array.isArray(events) ? events : []) {
29	        if (event?.type !== 'actions.requested') continue;
30	        const actions = Array.isArray(event.data?.actions) ? event.data.actions : [];
31	        for (const action of actions) {
32	            if (action?.kind !== 'tool-call' || action.toolName !== MEETING_NOTE_TOOL_NAME) continue;
33	            if (!action.input || typeof action.input !== 'object') continue;
34	            calls.push({ call_id: action.callId || null, input: action.input });
35	        }
36	    }
37	    return calls;
38	}
39	
40	/**
41	 * Classifies where an Eve session currently is, based on the terminal-most
42	 * event of the replayed stream. `parked` means the agent finished its turn
43	 * and is waiting for the next user message: no further tool calls will
44	 * arrive without new input, so a parked session without a note is final.
45	 */
46	export function classifySessionStreamPhase(events) {
47	    const list = Array.isArray(events) ? events : [];
48	    for (let index = list.length - 1; index >= 0; index -= 1) {
49	        switch (list[index]?.type) {
50	            case 'session.waiting':
51	                return 'parked';
52	            case 'session.completed':
53	                return 'completed';
54	            case 'session.failed':
55	            case 'turn.failed':
56	                return 'failed';
57	            case 'turn.started':
58	            case 'message.received':
59	                // A turn began after any earlier park: the session resumed.
60	                return 'in_progress';
61	            default:
62	                break;
63	        }
64	    }
65	    return 'in_progress';
66	}
67	
68	/**
69	 * Pull-based reconciler closing the Eve meeting-note loop.
70	 *
71	 * Eve (Vercel) cannot POST back to this Mac-local Brainbase instance, so the
72	 * dispatch run stays `running`/`await_eve_result` after the agent generates
73	 * the note. This worker polls the Eve session stream for each pending
74	 * dispatch run, extracts the generated note from the
75	 * `record_meeting_note_generation` tool-call input, verifies it against the
76	 * `run.metadata.meeting_note_generation` handoff (run_id + source_text_hash),
77	 * and records it through the local note-generation contract
78	 * (`workflowService.recordMeetingNoteGeneration`).
79	 */
80	export class EveMeetingNoteReconciler {
81	    constructor({
82	        workflowService,
83	        eveSessionClient,
84	        repository = null,
85	        config = {},
86	        clock = nowIso,
87	        logger = console
88	    }) {
89	        if (!workflowService) throw new Error('workflowService is required');
90	        this.workflowService = workflowService;
91	        this.eveSessionClient = eveSessionClient || workflowService.eveSessionClient || null;
92	        this.repository = repository || workflowService.repository;
93	        this.clock = clock;
94	        this.logger = logger;
95	        this.config = {
96	            enabled: config.enabled !== false,
97	            interval_ms: parseDurationMs(config.interval_ms ?? config.intervalMs, DEFAULT_INTERVAL_MS),
98	            immediate: config.immediate === true
99	        };
100	        this._scheduleTimer = null;
101	        this._runPromise = null;
102	    }
103	
104	    isConfigured() {
105	        return Boolean(this.eveSessionClient?.isConfigured?.());
106	    }
107	
108	    listPendingDispatchRuns() {
109	        this.repository.reload?.();
110	        return this.repository.listRuns({ limit: null })
111	            .filter((run) => run.env === 'eve')
112	            .filter((run) => run.status === 'running')
113	            .filter((run) => run.metadata?.meeting_note_generation?.run_id)
114	            .filter((run) => run.metadata?.runner?.session_id);
115	    }
116	
117	    async runOnce() {
118	        if (this._runPromise) return this._runPromise;
119	        this._runPromise = (async () => {
120	            const summary = {
121	                ran_at: this.clock(),
122	                configured: this.isConfigured(),
123	                checked: 0,
124	                recorded: 0,
125	                already_recorded: 0,
126	                blocked: 0,
127	                pending: 0,
128	                errors: []
129	            };
130	            if (!summary.configured) return summary;
131	            const runs = this.listPendingDispatchRuns();
132	            for (const run of runs) {
133	                summary.checked += 1;
134	                try {
135	                    const outcome = await this.reconcileRun(run);
136	                    if (outcome.status === 'recorded') summary.recorded += 1;
137	                    else if (outcome.status === 'already_recorded') summary.already_recorded += 1;
138	                    else if (outcome.status === 'blocked') summary.blocked += 1;
139	                    else summary.pending += 1;
140	                } catch (error) {
141	                    summary.errors.push({
142	                        run_id: run.id,
143	                        error: error?.message || String(error)
144	                    });
145	                    this.logger.warn?.(`[eve-note-reconciler] run ${run.id} failed: ${error?.message || error}`);
146	                }
147	            }
148	            return summary;
149	        })();
150	        try {
151	            return await this._runPromise;
152	        } finally {
153	            this._runPromise = null;
154	        }
155	    }
156	
157	    async reconcileRun(dispatchRun) {
158	        const meetingNoteGeneration = dispatchRun.metadata?.meeting_note_generation || {};
159	        const sessionId = dispatchRun.metadata?.runner?.session_id;
160	        const ingestRunId = meetingNoteGeneration.run_id;
161	
162	        if (this._targetAlreadyGenerated(ingestRunId)) {
163	            this._closeDispatchRun(dispatchRun, {
164	                status: 'success',
165	                reason: 'already_recorded',
166	                message: 'Meeting note was already recorded on the ingest run; closing the Eve dispatch run'
167	            });
168	            return { status: 'already_recorded', run_id: dispatchRun.id };
169	        }
170	
171	        const events = await this.eveSessionClient.readSessionStream({ sessionId });
172	        const noteCalls = extractMeetingNoteToolCalls(events);
173	        const matching = noteCalls.filter((call) => (
174	            call.input.source_text_hash === meetingNoteGeneration.source_text_hash
175	            && (!call.input.run_id || call.input.run_id === ingestRunId)
176	            && typeof call.input.note?.body === 'string'
177	            && call.input.note.body.trim() !== ''
178	        ));
179	        const noteCall = matching.at(-1) || null;
180	
181	        if (noteCall) {
182	            try {
183	                await this.workflowService.recordMeetingNoteGeneration({
184	                    org_id: dispatchRun.org_id,
185	                    project_id: dispatchRun.project_id,
186	                    run_id: ingestRunId,
187	                    source_text_hash: meetingNoteGeneration.source_text_hash,
188	                    note: {
189	                        ...(typeof noteCall.input.note.title === 'string' ? { title: noteCall.input.note.title } : {}),
190	                        body: noteCall.input.note.body
191	                    },
192	                    runner: { type: 'eve', session_id: sessionId }
193	                }, { ...RECONCILER_ACTOR });
194	            } catch (error) {
195	                // Validation/not-found failures are permanent for this dispatch
196	                // (e.g. the draft's source_text_hash diverged after a re-ingest,
197	                // or the ingest run was deleted): retrying every tick can never
198	                // succeed, so surface the run instead of polling it forever.
199	                if (error?.statusCode === 400 || error?.statusCode === 404) {
200	                    const blocked = this._blockDispatchRun(dispatchRun, {
201	                        phase: 'record_rejected',
202	                        reason: 'record_failed_permanent',
203	                        record_error: error?.message || String(error),
204	                        record_state_transition: error?.details?.state_transition || null
205	                    });
206	                    return { status: blocked ? 'blocked' : 'pending', run_id: dispatchRun.id, phase: 'record_rejected' };
207	                }
208	                throw error;
209	            }
210	            this._closeDispatchRun(dispatchRun, {
211	                status: 'success',
212	                reason: 'note_reconciled',
213	                message: 'Eve session meeting note reconciled into the meeting_note_draft output',
214	                note_call_id: noteCall.call_id
215	            });
216	            return { status: 'recorded', run_id: dispatchRun.id, note_call_id: noteCall.call_id };
217	        }
218	
219	        const phase = classifySessionStreamPhase(events);
220	        if (phase === 'in_progress') {
221	            return { status: 'pending', run_id: dispatchRun.id, phase };
222	        }
223	
224	        // The session reached a boundary (parked / completed / failed) without a
225	        // usable note tool-call: no further output will arrive without operator
226	        // input, so surface the run instead of polling it forever.
227	        const blocked = this._blockDispatchRun(dispatchRun, {
228	            phase,
229	            mismatched_note_calls: noteCalls.length - matching.length
230	        });
231	        return { status: blocked ? 'blocked' : 'pending', run_id: dispatchRun.id, phase };
232	    }
233	
234	    _targetAlreadyGenerated(ingestRunId) {
235	        if (!ingestRunId) return false;
236	        const output = this.repository.listOutputs(ingestRunId)
237	            .find((candidate) => candidate.metadata?.output_key === 'meeting_note_draft');
238	        return output?.payload?.generation_status === 'brainbase_generated';
239	    }
240	
241	    // Re-reads the run after the awaits so a concurrent writer (e.g. the
242	    // external-runner push ingest) is neither clobbered with a stale metadata
243	    // snapshot nor overwritten after it already closed the run.
244	    _freshRunningRun(dispatchRun) {
245	        const fresh = this.repository.getRun(dispatchRun.id);
246	        if (!fresh || fresh.status !== 'running') return null;
247	        return fresh;
248	    }
249	
250	    _closeDispatchRun(dispatchRun, { status, reason, message, note_call_id = null }) {
251	        const fresh = this._freshRunningRun(dispatchRun);
252	        if (!fresh) return false;
253	        const finishedAt = this.clock();
254	        this.repository.updateRun(fresh.id, {
255	            status,
256	            closure_state: 'closed',
257	            human_waiting: false,
258	            action_required: 'none',
259	            message,
260	            finished_at: finishedAt,
261	            metadata: {
262	                ...(fresh.metadata || {}),
263	                eve_note_reconciler: {
264	                    reconciled_at: finishedAt,
265	                    reason,
266	                    ...(note_call_id ? { note_call_id } : {})
267	                }
268	            }
269	        });
270	        this._writeReconcilerAudit(dispatchRun, 'workflow.meeting_pack.note_generation.reconciled', {
271	            reason,
272	            note_call_id,
273	            ingest_run_id: dispatchRun.metadata?.meeting_note_generation?.run_id || null
274	        });
275	    }
276	
277	    _blockDispatchRun(dispatchRun, {
278	        phase,
279	        mismatched_note_calls = 0,
280	        reason = 'session_ended_without_note',
281	        record_error = null,
282	        record_state_transition = null
283	    }) {
284	        const fresh = this._freshRunningRun(dispatchRun);
285	        if (!fresh) return false;
286	        const finishedAt = this.clock();
287	        const message = reason === 'record_failed_permanent'
288	            ? `Meeting note write-back was rejected permanently: ${record_error}`
289	            : `Eve session ended (${phase}) without a matching record_meeting_note_generation call`;
290	        // Match the operator-attention convention of the existing eve
291	        // timeout-recovery runs: human_waiting + open closure keep the run on
292	        // the companion approval attention surface until an operator acts.
293	        this.repository.updateRun(fresh.id, {
294	            status: 'blocked',
295	            closure_state: 'open',
296	            human_waiting: true,
297	            action_required: 'operator_review_eve_session',
298	            message,
299	            finished_at: finishedAt,
300	            metadata: {
301	                ...(fresh.metadata || {}),
302	                eve_note_reconciler: {
303	                    reconciled_at: finishedAt,
304	                    reason,
305	                    session_phase: phase,
306	                    mismatched_note_calls,
307	                    ...(record_error ? { record_error, record_state_transition } : {})
308	                }
309	            }
310	        });
311	        this._writeReconcilerAudit(dispatchRun, 'workflow.meeting_pack.note_generation.reconcile_blocked', {
312	            reason,
313	            session_phase: phase,
314	            mismatched_note_calls,
315	            ...(record_error ? { record_error, record_state_transition } : {}),
316	            ingest_run_id: dispatchRun.metadata?.meeting_note_generation?.run_id || null
317	        });
318	        return true;
319	    }
320	
321	    _writeReconcilerAudit(dispatchRun, action, after) {
322	        this.repository.writeAuditLog({
323	            workspace_id: dispatchRun.workspace_id,
324	            org_id: dispatchRun.org_id || null,
325	            project_id: dispatchRun.project_id,
326	            actor_id: RECONCILER_ACTOR.sub,
327	            action,
328	            target_type: 'workflow_run',
329	            target_id: dispatchRun.id,
330	            after: {
331	                eve_session_id: dispatchRun.metadata?.runner?.session_id || null,
332	                ...after
333	            }
334	        });
335	    }
336	
337	    startScheduledReconcile(options = {}) {
338	        const config = {
339	            ...this.config,
340	            ...options,
341	            interval_ms: parseDurationMs(options.interval_ms ?? options.intervalMs, this.config.interval_ms)
342	        };
343	        if (!config.enabled) return { started: false, reason: 'disabled' };
344	        if (!this.isConfigured()) return { started: false, reason: 'eve_not_configured' };
345	        if (this._scheduleTimer) return { started: false, reason: 'already_started' };
346	        this.config = config;
347	        const runTick = () => {
348	            void this.runOnce().catch((error) => {
349	                this.logger.warn?.(`[eve-note-reconciler] scheduled run failed: ${error?.message || error}`);
350	            });
351	        };
352	        this._scheduleTimer = setInterval(runTick, config.interval_ms);
353	        this._scheduleTimer.unref?.();
354	        if (config.immediate) runTick();
355	        return { started: true, interval_ms: config.interval_ms };
356	    }
357	
358	    stopScheduledReconcile() {
359	        if (!this._scheduleTimer) return { stopped: false, reason: 'not_started' };
360	        clearInterval(this._scheduleTimer);
361	        this._scheduleTimer = null;
362	        return { stopped: true };
363	    }
364	}
365	
366	export function createEveMeetingNoteReconcilerConfigFromEnv(env = process.env) {
367	    return {
368	        enabled: env.BRAINBASE_EVE_NOTE_RECONCILER_ENABLED !== '0',
369	        interval_ms: env.BRAINBASE_EVE_NOTE_RECONCILER_INTERVAL_MS,
370	        immediate: env.BRAINBASE_EVE_NOTE_RECONCILER_IMMEDIATE === '1'
371	    };
372	}
